+static void devm_phy_bulk_release(struct device *dev, void *res)
+{
+	struct phy_bulk_devres *devres = res;
+
+	if (devres->free_phys)
+		phy_bulk_put_all(dev, devres->num_phys, devres->phys);
+	else
+		phy_bulk_put(dev, devres->num_phys, devres->phys);
